from struct import pack, unpack

catboost_model.float_feature_borders = [
    [unpack("f", pack("f", border))[0] for border in borders]
    for borders in catboost_model.float_feature_borders
]


def predict_residual(features):
    values = [unpack("f", pack("f", value))[0] for value in features]
    return apply_catboost_model(values)
